@Override
public int hashCode() {
    int result = super.hashCode();
    result = 31 * result + Arrays.hashCode(bottom);
    result = 31 * result + Boolean.hashCode(openBottom);
    result = 31 * result + Arrays.hashCode(top);
    result = 31 * result + Boolean.hashCode(openTop);
    return result;
}
